//! The loot of natural blocks that break by themselves (tickexact 2026-11-10): a plant whose
//! support went ([`crate::terrain::plants`]), a block water washes away. The game's block loot
//! tables (`terrain::loot_tables`, generated by `redsim-fuzz natural-loot-gen`) evaluated as
//! `Block.getDrops(state, level, pos, null)` does: the loot context of a block broken with no tool
//! (`TOOL` = an empty stack: `match_tool` fails, enchantment levels are 0) and an explosion radius
//! only from an explosion; the table's random is its random sequence
//! (`level.getRandomSequence("minecraft:blocks/<id>")`, salted from the sandbox's seed:
//! `World::loot_salt`), drawn in the game's order:
//! - `LootPool.addRandomItems`: the pool's conditions, its rolls, then each roll's
//!   `addRandomItem`: every entry expanded in order (its conditions tested as it expands:
//!   `alternatives` stops at the first child that expands, `sequence` at the first that fails,
//!   `group` expands all), the valid ones weighed (`nextInt(total)` when more than one);
//! - the chosen entry's stack (`new ItemStack(item)`, count 1) through its own modifiers, then the
//!   pool's, then the table's, each modifier's conditions tested before it runs;
//! - each stack split at its max stack size (`createStackSplitter`); a stack of 0 still pops
//!   (`Block.popResource` draws its position before it checks for an empty stack).

use crate::block::Block;
use crate::entity::mob::loot::LootRandom;
use crate::pos::BlockPos;
use crate::world::World;

/// A JSON value (the tables' own format).
#[derive(Clone, Debug)]
pub enum J {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<J>),
    Obj(Vec<(String, J)>),
}

static NULL: J = J::Null;

impl J {
    fn get(&self, k: &str) -> &J {
        match self {
            J::Obj(v) => v.iter().find(|(kk, _)| kk == k).map(|(_, x)| x).unwrap_or(&NULL),
            _ => &NULL,
        }
    }

    fn str(&self) -> Option<&str> {
        match self {
            J::Str(s) => Some(s),
            _ => None,
        }
    }

    fn num(&self) -> Option<f64> {
        match self {
            J::Num(n) => Some(*n),
            _ => None,
        }
    }

    fn is_null(&self) -> bool {
        matches!(self, J::Null)
    }

    /// A field that holds one value or a list of them (`condition`, `modifier`): the values.
    fn list(&self) -> Vec<&J> {
        match self {
            J::Null => Vec::new(),
            J::Arr(a) => a.iter().collect(),
            x => vec![x],
        }
    }
}

/// A JSON text (what the generated tables hold: objects, arrays, strings, numbers, booleans).
pub fn parse(s: &str) -> Result<J, String> {
    let b = s.as_bytes();
    let mut i = 0;
    let v = value(b, &mut i)?;
    skip_ws(b, &mut i);
    if i != b.len() {
        return Err(format!("json: trailing text at {i}"));
    }
    Ok(v)
}

fn skip_ws(b: &[u8], i: &mut usize) {
    while *i < b.len() && b[*i].is_ascii_whitespace() {
        *i += 1;
    }
}

fn value(b: &[u8], i: &mut usize) -> Result<J, String> {
    skip_ws(b, i);
    match b.get(*i) {
        Some(b'{') => {
            *i += 1;
            let mut v = Vec::new();
            loop {
                skip_ws(b, i);
                if b.get(*i) == Some(&b'}') {
                    *i += 1;
                    return Ok(J::Obj(v));
                }
                let J::Str(k) = value(b, i)? else { return Err(format!("json: a key at {i}")) };
                skip_ws(b, i);
                if b.get(*i) != Some(&b':') {
                    return Err(format!("json: ':' at {i}"));
                }
                *i += 1;
                v.push((k, value(b, i)?));
                skip_ws(b, i);
                if b.get(*i) == Some(&b',') {
                    *i += 1;
                }
            }
        }
        Some(b'[') => {
            *i += 1;
            let mut v = Vec::new();
            loop {
                skip_ws(b, i);
                if b.get(*i) == Some(&b']') {
                    *i += 1;
                    return Ok(J::Arr(v));
                }
                v.push(value(b, i)?);
                skip_ws(b, i);
                if b.get(*i) == Some(&b',') {
                    *i += 1;
                }
            }
        }
        Some(b'"') => {
            *i += 1;
            let mut s = String::new();
            while let Some(&c) = b.get(*i) {
                *i += 1;
                match c {
                    b'"' => return Ok(J::Str(s)),
                    b'\\' => {
                        let e = *b.get(*i).ok_or("json: an escape at the end")?;
                        *i += 1;
                        s.push(match e {
                            b'n' => '\n',
                            b't' => '\t',
                            b'u' => {
                                let h = std::str::from_utf8(b.get(*i..*i + 4).ok_or("json: \\u")?).map_err(|e| e.to_string())?;
                                *i += 4;
                                char::from_u32(u32::from_str_radix(h, 16).map_err(|e| e.to_string())?).unwrap_or('?')
                            }
                            c => c as char,
                        });
                    }
                    _ => {
                        // the text is UTF-8: copy the bytes of a multi-byte character as they come
                        let start = *i - 1;
                        let mut end = *i;
                        while end < b.len() && (b[end] & 0xC0) == 0x80 {
                            end += 1;
                        }
                        s.push_str(std::str::from_utf8(&b[start..end]).map_err(|e| e.to_string())?);
                        *i = end;
                    }
                }
            }
            Err("json: an unterminated string".into())
        }
        Some(b't') if b[*i..].starts_with(b"true") => {
            *i += 4;
            Ok(J::Bool(true))
        }
        Some(b'f') if b[*i..].starts_with(b"false") => {
            *i += 5;
            Ok(J::Bool(false))
        }
        Some(b'n') if b[*i..].starts_with(b"null") => {
            *i += 4;
            Ok(J::Null)
        }
        Some(_) => {
            let start = *i;
            while *i < b.len() && matches!(b[*i], b'-' | b'+' | b'.' | b'e' | b'E' | b'0'..=b'9') {
                *i += 1;
            }
            let t = std::str::from_utf8(&b[start..*i]).map_err(|e| e.to_string())?;
            t.parse::<f64>().map(J::Num).map_err(|_| format!("json: a value at {start}"))
        }
        None => Err("json: unexpected end".into()),
    }
}

/// The parsed tables (block id without `minecraft:`; `None`: no table, it drops nothing).
fn tables() -> &'static Vec<(&'static str, Option<J>)> {
    static T: std::sync::OnceLock<Vec<(&'static str, Option<J>)>> = std::sync::OnceLock::new();
    T.get_or_init(|| {
        super::loot_tables::TABLES
            .iter()
            .map(|(id, text)| (*id, if text.is_empty() { None } else { Some(parse(text).unwrap_or_else(|e| panic!("the loot table of {id}: {e}"))) }))
            .collect()
    })
}

/// The block-entity-free loot context: the broken state, where, and the explosion radius.
struct Ctx<'a> {
    w: &'a World,
    pos: BlockPos,
    /// The state's block id (`minecraft:...`) and properties.
    id: String,
    props: Vec<(String, String)>,
    explosion: Option<f32>,
}

/// A game string's block id and properties.
fn split_state(s: &str) -> (String, Vec<(String, String)>) {
    match s.find('[') {
        Some(i) => (
            s[..i].to_string(),
            s[i + 1..].trim_end_matches(']').split(',').filter_map(|kv| kv.split_once('=')).map(|(k, v)| (k.to_string(), v.to_string())).collect(),
        ),
        None => (s.to_string(), Vec::new()),
    }
}

fn full_id(s: &str) -> String {
    if s.contains(':') { s.to_string() } else { format!("minecraft:{s}") }
}

/// A block predicate's `blocks` (one id or a list of ids; a tag is not modeled) and `state`
/// (exact values) against a block id and properties.
fn block_matches(blocks: &J, state: &J, id: &str, props: &[(String, String)]) -> Result<bool, String> {
    let ok_id = match blocks {
        J::Null => true,
        J::Str(s) if s.starts_with('#') => return Err(format!("loot: a block tag {s} in a block predicate is not modeled")),
        J::Str(s) => full_id(s) == id,
        J::Arr(a) => a.iter().filter_map(J::str).any(|s| full_id(s) == id),
        x => return Err(format!("loot: block predicate blocks {x:?}")),
    };
    if !ok_id {
        return Ok(false);
    }
    if let J::Obj(kv) = state {
        for (k, v) in kv {
            let want = match v {
                J::Str(s) => s.clone(),
                J::Num(n) => format!("{n}"),
                J::Bool(b) => b.to_string(),
                x => return Err(format!("loot: a state range {k} = {x:?} is not modeled")),
            };
            if !props.iter().any(|(pk, pv)| pk == k && *pv == want) {
                return Ok(false);
            }
        }
    }
    Ok(true)
}

/// A number provider's float (`getFloat`).
fn num_float(v: &J, r: &mut dyn LootRandom) -> Result<f32, String> {
    match v {
        J::Num(n) => Ok(*n as f32),
        J::Obj(_) => match v.get("type").str().map(|t| t.trim_start_matches("minecraft:")) {
            Some("constant") => Ok(v.get("value").num().unwrap_or(0.0) as f32),
            // UniformGenerator.getFloat: Mth.randomBetween(random, min, max)
            Some("uniform") => {
                let (lo, hi) = (num_float(v.get("min"), r)?, num_float(v.get("max"), r)?);
                Ok(r.next_float() * (hi - lo) + lo)
            }
            t => Err(format!("loot: number provider {t:?} is not modeled")),
        },
        x => Err(format!("loot: number {x:?}")),
    }
}

/// A number provider's int (`getInt`).
fn num_int(v: &J, r: &mut dyn LootRandom) -> Result<i32, String> {
    match v {
        J::Num(n) => Ok(n.floor() as i32),
        J::Obj(_) => match v.get("type").str().map(|t| t.trim_start_matches("minecraft:")) {
            Some("constant") => Ok(v.get("value").num().unwrap_or(0.0).floor() as i32),
            // UniformGenerator.getInt: Mth.nextInt(random, floor(min), floor(max))
            Some("uniform") => {
                let lo = num_float(v.get("min"), r)?.floor() as i32;
                let hi = num_float(v.get("max"), r)?.floor() as i32;
                Ok(if lo >= hi { lo } else { r.next_int(hi - lo + 1) + lo })
            }
            // BinomialDistributionGenerator.getInt: n trials of nextFloat() < p
            Some("binomial") => {
                let n = num_int(v.get("n"), r)?;
                let p = num_float(v.get("p"), r)?;
                Ok((0..n).filter(|_| r.next_float() < p).count() as i32)
            }
            t => Err(format!("loot: number provider {t:?} is not modeled")),
        },
        x => Err(format!("loot: number {x:?}")),
    }
}

/// A condition list (`allOf`: in order, stopping at the first false).
fn conds(c: &Ctx, v: &J, r: &mut dyn LootRandom) -> Result<bool, String> {
    for x in v.list() {
        if !cond(c, x, r)? {
            return Ok(false);
        }
    }
    Ok(true)
}

fn cond(c: &Ctx, v: &J, r: &mut dyn LootRandom) -> Result<bool, String> {
    let ty = v.get("type").str().unwrap_or("").trim_start_matches("minecraft:");
    Ok(match ty {
        "match_block" => block_matches(v.get("blocks"), v.get("state"), &c.id, &c.props)?,
        "location_check" => {
            let o = |k: &str| v.get(k).num().unwrap_or(0.0) as i32;
            let pred = v.get("predicate");
            if pred.is_null() {
                true
            } else {
                if let J::Obj(kv) = pred
                    && let Some((k, _)) = kv.iter().find(|(k, _)| k != "block")
                {
                    return Err(format!("loot: location_check predicate {k} is not modeled"));
                }
                let b = pred.get("block");
                if b.is_null() {
                    true
                } else {
                    let at = c.w.get(BlockPos::new(c.pos.x + o("offsetX"), c.pos.y + o("offsetY"), c.pos.z + o("offsetZ")));
                    let (id, props) = split_state(&at.to_string());
                    block_matches(b.get("blocks"), b.get("state"), &id, &props)?
                }
            }
        }
        "random_chance" => {
            let chance = num_float(v.get("chance"), r)?;
            r.next_float() < chance
        }
        // RandomChanceWithEnchantedBonusCondition: no tool, the unenchanted chance
        "random_chance_with_enchanted_bonus" => {
            let chance = num_float(v.get("unenchanted_chance"), r)?;
            r.next_float() < chance
        }
        "survives_explosion" => match c.explosion {
            Some(radius) => r.next_float() <= 1.0 / radius,
            None => true,
        },
        // TableBonusCondition: enchantment level 0
        "table_bonus" => {
            let first = match v.get("chances") {
                J::Arr(a) => a.first().and_then(J::num).unwrap_or(0.0) as f32,
                x => return Err(format!("loot: table_bonus chances {x:?}")),
            };
            r.next_float() < first
        }
        // MatchTool: the empty stack fails any predicate that names something
        "match_tool" => match v.get("predicate") {
            J::Null => true,
            J::Obj(kv) => kv.is_empty(),
            _ => false,
        },
        "inverted" => !cond(c, v.get("term"), r)?,
        "any_of" => {
            for t in v.get("terms").list() {
                if cond(c, t, r)? {
                    return Ok(true);
                }
            }
            false
        }
        "all_of" => {
            for t in v.get("terms").list() {
                if !cond(c, t, r)? {
                    return Ok(false);
                }
            }
            true
        }
        t => return Err(format!("loot: condition {t} is not modeled for a block")),
    })
}

/// A stack's modifiers (`modifier` / `functions`), in order, each one's conditions first.
fn modify(c: &Ctx, fs: &J, stack: &mut (String, i32), r: &mut dyn LootRandom) -> Result<(), String> {
    for f in fs.list() {
        let fc = if f.get("condition").is_null() { f.get("conditions") } else { f.get("condition") };
        if !conds(c, fc, r)? {
            continue;
        }
        let ty = f.get("type").str().unwrap_or("").trim_start_matches("minecraft:");
        match ty {
            "set_count" => {
                let add = matches!(f.get("add"), J::Bool(true));
                let n = num_int(f.get("count"), r)?;
                stack.1 = if add { stack.1 } else { 0 } + n;
            }
            "apply_bonus" => {
                // no tool: enchantment level 0
                let fm = f.get("formula").str().unwrap_or("").trim_start_matches("minecraft:");
                let params = f.get("parameters");
                match fm {
                    "uniform_bonus_count" => {
                        let _ = params.get("bonusMultiplier");
                        stack.1 += r.next_int(1);
                    }
                    "binomial_with_bonus_count" => {
                        let extra = params.get("extra").num().unwrap_or(0.0) as i32;
                        let p = params.get("probability").num().unwrap_or(0.0) as f32;
                        for _ in 0..extra {
                            if r.next_float() < p {
                                stack.1 += 1;
                            }
                        }
                    }
                    "ore_drops" => {}
                    o => return Err(format!("loot: apply_bonus formula {o} is not modeled")),
                }
            }
            "explosion_decay" => {
                if let Some(radius) = c.explosion {
                    let p = 1.0 / radius;
                    let n = stack.1;
                    stack.1 = (0..n).filter(|_| r.next_float() <= p).count() as i32;
                }
            }
            "limit_count" => {
                let l = f.get("limit");
                let (lo, hi) = match l {
                    J::Num(n) => (Some(*n as i32), Some(*n as i32)),
                    _ => (l.get("min").num().map(|x| x as i32), l.get("max").num().map(|x| x as i32)),
                };
                if let Some(lo) = lo {
                    stack.1 = stack.1.max(lo);
                }
                if let Some(hi) = hi {
                    stack.1 = stack.1.min(hi);
                }
            }
            // components: nothing drawn, nothing redsim's items carry
            "copy_components" | "copy_state" | "copy_name" | "set_components" | "set_name" | "set_lore" | "copy_custom_data" | "set_custom_data" => {}
            t => return Err(format!("loot: modifier {t} is not modeled for a block")),
        }
    }
    Ok(())
}

/// `LootPoolEntryContainer.expand`: the singleton entries this one yields (conditions tested as it
/// expands), and whether it expanded.
fn expand<'a>(c: &Ctx, e: &'a J, r: &mut dyn LootRandom, out: &mut Vec<&'a J>) -> Result<bool, String> {
    let ec = if e.get("condition").is_null() { e.get("conditions") } else { e.get("condition") };
    let ty = e.get("type").str().unwrap_or("").trim_start_matches("minecraft:");
    match ty {
        "item" | "empty" => {
            if conds(c, ec, r)? {
                out.push(e);
                Ok(true)
            } else {
                Ok(false)
            }
        }
        "alternatives" | "sequence" | "group" => {
            if !conds(c, ec, r)? {
                return Ok(false);
            }
            for ch in e.get("children").list() {
                let ok = expand(c, ch, r, out)?;
                match ty {
                    "alternatives" if ok => return Ok(true),
                    "sequence" if !ok => return Ok(false),
                    _ => {}
                }
            }
            Ok(ty != "alternatives")
        }
        t => Err(format!("loot: entry {t} is not modeled for a block")),
    }
}

fn weight(e: &J) -> i32 {
    e.get("weight").num().map(|w| w.floor() as i32).unwrap_or(1).max(0)
}

/// `LootTable.getRandomItems` of a table in context `c`: the stacks in the order they pop.
fn roll(c: &Ctx, t: &J, r: &mut dyn LootRandom) -> Result<Vec<(String, i32)>, String> {
    let mut out = Vec::new();
    let table_fns = if t.get("modifier").is_null() { t.get("functions") } else { t.get("modifier") };
    for pool in t.get("pools").list() {
        let pc = if pool.get("condition").is_null() { pool.get("conditions") } else { pool.get("condition") };
        if !conds(c, pc, r)? {
            continue;
        }
        let rolls = num_int(pool.get("rolls"), r)?;
        // bonus rolls: getFloat times the luck (0)
        if !pool.get("bonus_rolls").is_null() {
            num_float(pool.get("bonus_rolls"), r)?;
        }
        let pool_fns = if pool.get("modifier").is_null() { pool.get("functions") } else { pool.get("modifier") };
        for _ in 0..rolls {
            let mut valid = Vec::new();
            for e in pool.get("entries").list() {
                expand(c, e, r, &mut valid)?;
            }
            valid.retain(|e| weight(e) > 0);
            let total: i32 = valid.iter().map(|e| weight(e)).sum();
            if total == 0 || valid.is_empty() {
                continue;
            }
            let chosen = if valid.len() == 1 {
                valid[0]
            } else {
                let mut k = r.next_int(total);
                let mut pick = valid[0];
                for e in &valid {
                    k -= weight(e);
                    if k < 0 {
                        pick = e;
                        break;
                    }
                }
                pick
            };
            if chosen.get("type").str().unwrap_or("").trim_start_matches("minecraft:") == "empty" {
                continue;
            }
            let name = chosen.get("name").str().ok_or("loot: an item entry without a name")?;
            let mut stack = (full_id(name), 1);
            let ef = if chosen.get("modifier").is_null() { chosen.get("functions") } else { chosen.get("modifier") };
            modify(c, ef, &mut stack, r)?;
            modify(c, pool_fns, &mut stack, r)?;
            modify(c, table_fns, &mut stack, r)?;
            // createStackSplitter: a stack at or over its max stack size goes out in pieces
            let max = crate::loot::max_stack(&stack.0) as i32;
            if stack.1 < max {
                out.push(stack);
            } else {
                let mut n = stack.1;
                while n > 0 {
                    let k = n.min(max);
                    out.push((stack.0.clone(), k));
                    n -= k;
                }
            }
        }
    }
    Ok(out)
}

/// Whether redsim holds the loot table of natural block `id` (`minecraft:` id).
pub fn knows(id: &str) -> bool {
    let short = id.trim_start_matches("minecraft:");
    tables().iter().any(|(t, _)| *t == short)
}

/// `Block.getDrops` of the natural state `s` broken at `pos` (an explosion's radius when it is
/// one): the stacks (item id, count; a count may be 0), drawn from the table's random sequence
/// (taken from `World::loot_sequences`, made on first use from `World::loot_salt`). A block whose
/// table redsim does not hold, or a table using what redsim does not model: why.
pub fn drops(w: &mut World, s: &Block, pos: BlockPos, explosion: Option<f32>) -> Result<Vec<(String, i32)>, String> {
    let name = s.to_string();
    let (id, props) = split_state(&name);
    let short = id.trim_start_matches("minecraft:").to_string();
    let Some((_, table)) = tables().iter().find(|(t, _)| *t == short) else {
        return Err(format!("the drops of natural {name}: no loot table known to redsim (redsim-fuzz natural-loot-gen)"));
    };
    let Some(t) = table else { return Ok(Vec::new()) };
    let Some(key) = t.get("random_sequence").str() else {
        return Err(format!("the drops of natural {name}: a table without a random sequence draws from the level random (not modeled)"));
    };
    let salt = w.loot_salt.unwrap_or(0);
    let mut seq = w.loot_sequences.remove(key).unwrap_or_else(|| crate::stems::LootSequence::new(salt, key));
    let r = {
        let c = Ctx { w, pos, id, props, explosion };
        roll(&c, t, &mut seq)
    };
    w.loot_sequences.insert(key.to_string(), seq);
    r.map_err(|e| format!("the drops of natural {name}: {e}"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_table_parses() {
        assert!(tables().len() > 50);
        assert!(knows("minecraft:leaf_litter") && knows("minecraft:short_grass"));
    }

    #[test]
    fn leaf_litter_drops_its_segments_and_draws_nothing() {
        let mut w = World::new(BlockPos::new(0, 0, 0), [4, 4, 4]);
        let s = crate::terrain::land::block_of("minecraft:leaf_litter[facing=north,segment_amount=3]").unwrap();
        let v = drops(&mut w, &s, BlockPos::new(1, 1, 1), None).unwrap();
        assert_eq!(v, vec![("minecraft:leaf_litter".to_string(), 3)]);
        // the table drew nothing: its sequence is where a fresh one starts
        let fresh = crate::stems::LootSequence::new(0, "minecraft:blocks/leaf_litter");
        assert_eq!(w.loot_sequences.get("minecraft:blocks/leaf_litter"), Some(&fresh));
    }
}
